-- CraveCircle: 50 curated Food.com seed recipes. Generated from cravecircle_50_recipes.json.
-- Target: cravecircle.recipes. Run in the Supabase SQL editor.
--
-- Owner: the profile whose username is set below. Use a dedicated kitchen account, NOT your
-- own: recipes you own count as yours (Your Library) and are left out of Fresh / Suggested.
-- Photos: thumbnail_url is the full public URL in the recipe-thumbnails bucket, with ?v=N
-- to get past Cloudflare's cache (upload with upload_images.sh first).
-- Safe to re-run: existing ids only get their photo URL and nutrition refreshed.

SET search_path = cravecircle, public;

DO $$
DECLARE
    seed_username text := 'aicookbook';   -- house creator account that owns the built-in samples
    seed_owner uuid;
BEGIN
    SELECT id INTO seed_owner FROM cravecircle.profiles WHERE username = seed_username;
    IF seed_owner IS NULL THEN
        RAISE EXCEPTION 'No profile with username %. Sign up that account in the app first.', seed_username;
    END IF;

    INSERT INTO cravecircle.recipes (id, owner_id, title, description, prep_time, cook_time, servings,
        ingredients, directions, thumbnail_url, owner_username, source_language, nutrition, visibility)
    VALUES
        ('recipe-lasagna-bolognese', seed_owner, 'Ultimate Italian Lasagna Bolognese', 'My family''s favorite. This is a very meaty lasagna. We prefer it with cottage cheese, but you can easily substitute ricotta.', '53 min', '1 hr 37 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g lean ground beef", "Italian sausage", "1 medium diced onion", "3 cloves minced garlic", "1 tsp salt", "0.5 tsp fresh coarse ground black pepper", "2 tbsp dried parsley flakes", "2 tbsp dried oregano", "2 tbsp dried basil", "2 cups whole tomatoes", "1 cup ricotta cheese", "2 large eggs", "0.5 tsp pepper", "2 tbsp fresh parsley", "0.5 cup grated parmesan cheese", "1.5 cups shredded mozzarella cheese", "2 cups lasagna noodles"]}]'::jsonb, '[{"stepIndex": 1, "text": "Brown ground meat, onion and garlic."}, {"stepIndex": 2, "text": "Add salt, pepper, parsley, oregano, basil, chopped tomatoes with juice."}, {"stepIndex": 3, "text": "Stirring until well mixed."}, {"stepIndex": 4, "text": "Cover and simmer 1 hour."}, {"stepIndex": 5, "text": "Cook lasagna noodles according to package directions."}, {"stepIndex": 6, "text": "Drain and set aside."}, {"stepIndex": 7, "text": "Spray a 13 x 9\" baking pan with cooking spray."}, {"stepIndex": 8, "text": "Combine riccota cheese, eggs, pepper, 2 tablespoons parsley, parmesan cheese and 1/2 1lb of mozzarella cheese."}, {"stepIndex": 9, "text": "In a lasagna pan, layer noodles, meat sauce, and cheese mixture."}, {"stepIndex": 10, "text": "Repeat."}, {"stepIndex": 11, "text": "Top off with layer of noodles."}, {"stepIndex": 12, "text": "Sprinkle evenly with remaining mozzarella cheese."}, {"stepIndex": 13, "text": "Make sure to cover noodles completely."}, {"stepIndex": 14, "text": "Bake at 375°F for 40-60 minutes, or until cheese mixture is thoroughly melted."}, {"stepIndex": 15, "text": "(I cover with foil for about 40 minutes, then uncover for 15-20 minutes."}, {"stepIndex": 16, "text": "Let sit for 15-20 minutes before cutting and serving."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_lasagna_bolognese.jpg?v=1', '@chef_marco', 'en', '{"calories": 517, "carbsG": 58.2, "proteinG": 32.3, "fatG": 17.2, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-fettuccine-alfredo', seed_owner, 'Creamy Fettuccine Alfredo', 'Just like the famous restaraunt''s dish.', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "1 cup cream cheese", "1 cup heavy cream", "3 cloves minced garlic powder", "1 tsp salt", "0.5 tsp black pepper", "0.5 cup grated parmesan cheese", "Fettuccine"]}]'::jsonb, '[{"stepIndex": 1, "text": "In a medium saucepan, melt butter."}, {"stepIndex": 2, "text": "When butter is melted, add cream cheese."}, {"stepIndex": 3, "text": "When the cream cheese is softened, add heavy cream."}, {"stepIndex": 4, "text": "Season with garlic powder, salt, and pepper."}, {"stepIndex": 5, "text": "Simmer for 15-20 minutes over low heat, stirring constantly."}, {"stepIndex": 6, "text": "Remove from heat and stir in parmesan."}, {"stepIndex": 7, "text": "Serve over hot fettucine noodles."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_fettuccine_alfredo.jpg?v=1', '@elena_bakes', 'en', '{"calories": 880, "carbsG": 99.0, "proteinG": 55.0, "fatG": 29.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-gourmet-mushroom-risotto', seed_owner, 'Gourmet Wild Mushroom Risotto', 'In college, my friend angela and I went to visit her granny. She made this for us. It was the first time i''d ever experienced anything like it. It was delicious and her granny gladly gave me the recipe.', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g chicken broth", "2 tbsp oil", "White mushrooms", "Shallots", "1.5 cups arborio rice", "Dry white wine", "1 tsp salt", "0.5 tsp black pepper", "Chives", "2 tbsp butter", "0.5 cup grated parmesan cheese"]}]'::jsonb, '[{"stepIndex": 1, "text": "Heat the broth over low heat."}, {"stepIndex": 2, "text": "In a large saucepan, heat 2 tablespoons of oil and cook the mushrooms until soft."}, {"stepIndex": 3, "text": "About 3 minute."}, {"stepIndex": 4, "text": "Put the mushrooms and the liquid in a bowl and set aside."}, {"stepIndex": 5, "text": "Add the remaining 1 tablespoons oil to skillet, and cook the shallots for 1 minute."}, {"stepIndex": 6, "text": "Stir in the rice, coating it with oil, about 2 minutes."}, {"stepIndex": 7, "text": "When the rice has taken on a pale, golden color, add the wine, stirring constantly until it is fully absorbed."}, {"stepIndex": 8, "text": "Add 1/2 cup broth to the rice, and stir until the broth is absorbed."}, {"stepIndex": 9, "text": "Continue adding broth 1/2 cup at a time, stirring continuously, until the liquid is absorbed and the rice is tender-firm."}, {"stepIndex": 10, "text": "Remove from heat, and stir in mushrooms with their liquid, butter, chives, and parmesan."}, {"stepIndex": 11, "text": "Season with salt and pepper to taste."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_gourmet_mushroom_risotto.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 424, "carbsG": 47.7, "proteinG": 26.5, "fatG": 14.1, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-crispy-chicken-parmesan', seed_owner, 'Crispy Chicken Parmesan', 'An easy dish with lots of flavor. It is one of those dishes I get a craving for.', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups angel hair pasta", "500g boneless skinless chicken breast halves", "1 large egg", "Italian seasoned breadcrumbs", "2 tbsp butter", "0.5 cup spaghetti sauce", "1.5 cups shredded mozzarella cheese", "0.5 cup grated parmesan cheese", "2 tbsp fresh fresh parsley"]}]'::jsonb, '[{"stepIndex": 1, "text": "Place the chicken between two sheets of heavy duty plastic wrap and flatten to about 1/4 inch thickness using a meat mallet or rolling pin."}, {"stepIndex": 2, "text": "Dip chicken in the egg and coat with breadcrumbs."}, {"stepIndex": 3, "text": "Melt butter in a large skillet over medium heat."}, {"stepIndex": 4, "text": "Add the chicken and cook for 8 minutes on each side or until chicken is fork tender and no pink remains."}, {"stepIndex": 5, "text": "While chicken is cooking, bring water to a boil for pasta."}, {"stepIndex": 6, "text": "When chicken is cooked, pour spaghetti sauce into pan around chicken."}, {"stepIndex": 7, "text": "Turn heat to low and heat sauce thoroughly."}, {"stepIndex": 8, "text": "Cook pasta according to package directions."}, {"stepIndex": 9, "text": "Place the angel hair on a serving platter, top with the chicken breasts."}, {"stepIndex": 10, "text": "Pour the sauce over chicken and sprinkle with the cheeses."}, {"stepIndex": 11, "text": "Garnish with the parsley or basil."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_crispy_chicken_parmesan.jpg?v=1', '@nada_dl', 'en', '{"calories": 698, "carbsG": 78.5, "proteinG": 43.6, "fatG": 23.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-carbonara', seed_owner, 'Carbonara', 'This is a recipe I cut out of a woman''s day magazine from rachel ray. I was unable to found this on her web site. We have this several times a month. I do cook the pasta for about 11 minutes.', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 tsp salt & freshly ground black pepper", "2 cups pasta", "2 tbsp extra virgin olive oil", "Pancetta", "0.5 tsp red pepper flakes", "3 cloves minced garlic", "Dry white wine", "1 large egg yolks", "1 cup romano cheese"]}]'::jsonb, '[{"stepIndex": 1, "text": "Put a large saucepot of water to boil."}, {"stepIndex": 2, "text": "Once boiling, add a liberal amount of salt and pasta."}, {"stepIndex": 3, "text": "Cook to al dente, about 8 minutes."}, {"stepIndex": 4, "text": "Meanwhile, heat a large skillet over medium heat."}, {"stepIndex": 5, "text": "Add olive oil and pancetta."}, {"stepIndex": 6, "text": "Brown pancetta about 2 minutes."}, {"stepIndex": 7, "text": "Add red pepper flakes and garlic and cook 2 to 3 minutes more."}, {"stepIndex": 8, "text": "Add wine and stir up all pan drippings."}, {"stepIndex": 9, "text": "In separate bowl, beat yolks, then add 1 large ladleful of the pasta cooking water."}, {"stepIndex": 10, "text": "This tempers the eggs and keeps them from scrambling when added to pasta."}, {"stepIndex": 11, "text": "Drain pasta well and add directly to skillet with pancetta, garlic and oil."}, {"stepIndex": 12, "text": "Pour egg mixture over pasta."}, {"stepIndex": 13, "text": "Toss rapidly to coat the pasta without cooking the egg."}, {"stepIndex": 14, "text": "Remove from heat and add a big handful of cheese, lots of pepper and a little salt."}, {"stepIndex": 15, "text": "Continue to toss and turn pasta until soaks up egg mixture and thickens, 1 to 2 minutes."}, {"stepIndex": 16, "text": "Serve with extra romano."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_carbonara.jpg?v=1', '@aditya_eats', 'en', '{"calories": 600, "carbsG": 67.5, "proteinG": 37.5, "fatG": 20.0, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-chicken-gnocchi-soup', seed_owner, 'Creamy Chicken and Gnocchi Soup', 'This is very close to the olive garden soup. There''s another recipe on the web, which was the basis of this recipe, however, I have changed it to use less cream. Still tastes good! I did end up using a little cornstarch to thicken. I guess you could sub heavy cream for the half-and-half to make it a little thicker without using cornstarch. The gnocchi is usually in the spaghetti section of the grocery store.', '13 min', '22 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g chicken breasts", "500g chicken stock", "Half-and-half", "Celery", "3 cloves minced garlic clove", "Carrot", "1 medium diced onion", "Fresh spinach", "2 tbsp olive oil", "Thyme", "1 tsp salt and pepper", "2 cups potato gnocchi", "Cornstarch"]}]'::jsonb, '[{"stepIndex": 1, "text": "Saute the onion, celery, garlic, carrot in oil over medium heat until onion is translucent."}, {"stepIndex": 2, "text": "Add chicken, chicken stock, half and half, salt and pepper, thyme."}, {"stepIndex": 3, "text": "Heat to boiling, then add gnocchi."}, {"stepIndex": 4, "text": "Gently boil for 4 minutes, then turn down to a simmer for 10 minutes."}, {"stepIndex": 5, "text": "Add spinach and cook for another 1-2 minutes until spinach is wilted."}, {"stepIndex": 6, "text": "Ladle into bowls and serve!."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_chicken_gnocchi_soup.jpg?v=1', '@maria_cocina', 'en', '{"calories": 236, "carbsG": 26.6, "proteinG": 14.8, "fatG": 7.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-artichoke-bruschetta', seed_owner, 'Toasted Artichoke and Herb Bruschetta', 'A really great tapa that will get you many compliments. Really simple to make. The original recipe was by roxanne. I have served this at many of my "wine and tapa" parties and was always pleased by the response.', '6 min', '11 min', 4, '[{"groupName": "Main Ingredients", "items": ["Marinated artichoke hearts", "2 cups tomatoes", "1 cup romano cheese", "1 medium diced red onion", "3 cloves minced garlic", "Mayonnaise", "French baguette"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat the broiler."}, {"stepIndex": 2, "text": "Place the bread slices on a baking sheet and toast lightly under the broiler."}, {"stepIndex": 3, "text": "In a medium bowl, mix marinated artichoke hearts, romano or parmesan cheese, red onion, crushed garlic, diced tomato and mayonnaise."}, {"stepIndex": 4, "text": "Top the lightly toasted french baguette slices with equal amounts of the artichoke heart mixture being careful to spread the mixture over the entire surface."}, {"stepIndex": 5, "text": "The edges of the bread will tend to burn if not covered by the artichoke mixture."}, {"stepIndex": 6, "text": "Arrange slices in a single layer on the baking sheet."}, {"stepIndex": 7, "text": "Broil in the preheated oven 2 minutes, or until toppings are bubbly and lightly browned."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_artichoke_bruschetta.jpg?v=1', '@sophie_table', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-garden-minestrone', seed_owner, 'Hearty Garden Minestrone Soup', 'A hearty and healthy soup. Excellent on chilly days. Very easy to prepare.', '20 min', '35 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp extra virgin olive oil", "1 medium diced onion", "1 cup water", "Zucchini", "Carrot", "2 cups cannellini beans", "Celery", "2 tbsp dried basil", "2 tbsp dried oregano", "1 tsp salt", "0.5 tsp fresh coarse ground black pepper", "2 cups canned plum tomatoes", "3 cloves minced garlic", "Ditalini"]}]'::jsonb, '[{"stepIndex": 1, "text": "Heat oil in a large saucepan over medium-high heat."}, {"stepIndex": 2, "text": "Add chopped onion and saut for 4 minutes or until just lightly browned."}, {"stepIndex": 3, "text": "Add water, zucchini, carrots, canellini beans, celery, basil, oregano salt, pepper, tomatoes and garlic."}, {"stepIndex": 4, "text": "Bring to boil."}, {"stepIndex": 5, "text": "Reduce heat, cover and simmer on medium-low heat for 25 minutes, stirring occasionally."}, {"stepIndex": 6, "text": "Add macaroni, cover and cook an additional 10 minutes."}, {"stepIndex": 7, "text": "Adjust spices to suit your taste."}, {"stepIndex": 8, "text": "Serve hot."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_garden_minestrone.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 172, "carbsG": 19.4, "proteinG": 10.8, "fatG": 5.7, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-sour-cream-enchiladas', seed_owner, 'Creamy Sour Cream Chicken Enchiladas', 'Easy to assemble, deliciously creamy and a great choice for once-a-month cooking. And there is no canned cream soup in my enchiladas -- hope you give them a try!', '16 min', '29 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g chicken breast", "1 medium diced onion", "2 tbsp vegetable oil", "1 cup flour tortillas", "1 cup monterey jack cheese", "2 tbsp butter", "1 cup flour", "500g chicken broth", "Sour cream", "Green chilies"]}]'::jsonb, '[{"stepIndex": 1, "text": "In a frying pan, cook chicken and onion together in oil over medium-high heat until chicken is just done."}, {"stepIndex": 2, "text": "Divide cooked chicken evenly between 8 tortillas."}, {"stepIndex": 3, "text": "Add 1 1/2 tablespoons cheese to each tortilla."}, {"stepIndex": 4, "text": "Roll enchiladas and place seam-side down in a 9x13\" baking dish that has been lightly sprayed with no-stick cooking spray."}, {"stepIndex": 5, "text": "Melt butter in a medium saucepan."}, {"stepIndex": 6, "text": "Stir in flour to make a roux, stir and cook until bubbly, and gradually whisk in chicken broth then bring to boiling, stirring frequently."}, {"stepIndex": 7, "text": "Remove from heat."}, {"stepIndex": 8, "text": "Stir in sour cream and green chilies."}, {"stepIndex": 9, "text": "Pour sauce evenly over enchiladas."}, {"stepIndex": 10, "text": "Top with remaining 3/4 cup cheese and bake at 400°F for 20 minutes until cheese is melted and sauce near edges of baking dish is bubbly."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_sour_cream_enchiladas.jpg?v=1', '@chef_marco', 'en', '{"calories": 507, "carbsG": 57.0, "proteinG": 31.7, "fatG": 16.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-sizzling-steak-fajitas', seed_owner, 'Sizzling Steak and Pepper Fajitas', 'These are so quick and tasty. You can use strips of boneless chicken breast instead of the beef. Feel free to double the marinade. The flavor is so great for such a short marination time. You can can do them up ahead of time and have the meat sit longer if you wish.', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["Top sirloin steak", "2 tbsp olive oil", "1 tbsp lime juice", "3 cloves minced garlic clove", "1 tsp chili powder", "1 tsp cumin", "0.5 tsp hot pepper flakes", "0.5 tsp black pepper", "1 tsp salt", "1 cup flour tortillas", "1 medium diced onion", "0.5 tsp sweet peppers", "Salsa", "Sour cream", "1 cup cheese", "2 cups chopped tomato"]}]'::jsonb, '[{"stepIndex": 1, "text": "Slice steak into thin strips."}, {"stepIndex": 2, "text": "In bowl, mix together 1 tablespoons olive oil, lime juice, garlic, chili powder, cumin, hot pepper flakes, black pepper & salt."}, {"stepIndex": 3, "text": "Add beef strips and stir to coat, set aside."}, {"stepIndex": 4, "text": "Wrap tortillas in foil and place in 350 oven for 5-10 minutes or until heated through."}, {"stepIndex": 5, "text": "Cut onions in half lengthwise and slice into strips, cut your peppers into strips."}, {"stepIndex": 6, "text": "In large non stick skillet over medium high heat, heat remaining tablespoons of olive oil."}, {"stepIndex": 7, "text": "Add onions & peppers stirring for 3-4 minutes, until softened."}, {"stepIndex": 8, "text": "Transfer to a bowl and set aside."}, {"stepIndex": 9, "text": "Add beef to skillet, cook, stirring for 3-4 minutes or until they lose their red color."}, {"stepIndex": 10, "text": "Return onions and peppers to skillet."}, {"stepIndex": 11, "text": "Stir for about one minute."}, {"stepIndex": 12, "text": "To serve, spoon a portion of the beef mixture down the centre of each tortilla, top with your desired toppings, fold bottom of tortilla up over filling, fold the sides in, overlapping."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_sizzling_steak_fajitas.jpg?v=1', '@elena_bakes', 'en', '{"calories": 137, "carbsG": 15.4, "proteinG": 8.6, "fatG": 4.6, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-fresh-chunky-guacamole', seed_owner, 'Classic Fresh Chunky Guacamole', 'This is a true tex-mex recipe concocted by a distant relative stationed at the alamo nearly 160 years ago. According to family lore, he was out looking for some good tomatoes when santa ana attacked the now famous texas landmark. Luckily, our relative kept this recipe in the lining of his coon-skin cap, and both he and his avocado dip lived to fight another day. Years later, near death from an infected chihuahua bite, he looked deep into his son''s eyes, and with his last breath, uttered the familiar phrase "remember... The...guacamole."', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["Avocados", "3 cloves minced garlic", "Lime", "2 cups tomatoes", "1 medium diced onion", "1 tsp salt", "2 tbsp fresh cilantro", "0.5 tsp jalapeno peppers"]}]'::jsonb, '[{"stepIndex": 1, "text": "Cut avocados in half, remove pit, and spoon avocado into a mixing bowl."}, {"stepIndex": 2, "text": "Add minced garlic and squeeze the juice from one-half of the lime into the bowl of avocado."}, {"stepIndex": 3, "text": "Mash the ingredients together to desired consistency using the back of a large spoon or a potato masher."}, {"stepIndex": 4, "text": "Fold in diced tomato and diced onion, a couple pinches of salt, and the juice from the remaining lime half."}, {"stepIndex": 5, "text": "Cover the bowl and refrigerate for 30-45 minutes."}, {"stepIndex": 6, "text": "Uncover and taste."}, {"stepIndex": 7, "text": "Add salt as needed."}, {"stepIndex": 8, "text": "If you don''t give the resulting guacamole at least 4 stars, then you ain''t making it right."}, {"stepIndex": 9, "text": "Some folks use lemon, but it''s been my experience that if you accidentally add too much lemon, it seriously affects the guacamole''s flavor."}, {"stepIndex": 10, "text": "If you happen to add too much lime, the guacamole just gets a little more tangy."}, {"stepIndex": 11, "text": "If you find the leftover guacamole has darkened, simply stir it before eating and use more fresh lime juice next time."}, {"stepIndex": 12, "text": "Wholly guacamole may be used as a topper with tacos, enchiladas, fajitas, etc."}, {"stepIndex": 13, "text": "However, some say it is at its best with a bowl of warm tortilla chips and an ice cold beer."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_fresh_chunky_guacamole.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 500, "carbsG": 56.2, "proteinG": 31.2, "fatG": 16.7, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-cheesy-chicken-quesadillas', seed_owner, 'Crispy Cheesy Chicken Quesadillas', 'I used to love these when I was younger, I could eat two in one sitting! I haven''t had fast food in a year or two, but these taste like I remember taco bell''s quesadillas tasting. I hope you enjoy it as much as I do.', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["Mayonnaise", "Jalapenos", "1 tbsp jalapeno juice", "0.5 cup sugar", "1 tsp cumin", "1 tsp paprika", "0.5 tsp cayenne pepper", "3 cloves minced garlic powder", "1 tsp salt", "1 cup flour tortillas", "500g chicken tenderloins", "1 cup shredded cheddar cheese", "1 cup monterey jack cheese", "1 cup process american cheese"]}]'::jsonb, '[{"stepIndex": 1, "text": "Combine sauce ingredients and stir until smooth."}, {"stepIndex": 2, "text": "Grill chicken in vegetable oil and cut into thin slices."}, {"stepIndex": 3, "text": "Preheat skillet over medium heat."}, {"stepIndex": 4, "text": "One at a time, lay tortilla into hot skillet and sprinkle with 1/4 cup of each shredded cheese and 1/2 cheese slice on one side of the tortilla."}, {"stepIndex": 5, "text": "Arrange about 1/4 cup chicken slices over tortilla on the same half covered with cheese."}, {"stepIndex": 6, "text": "On the empty side, spread about one tablespoon of sauce."}, {"stepIndex": 7, "text": "Fold over, and press gently with spatula."}, {"stepIndex": 8, "text": "Cook until cheese is melted and slice each into 4 pieces."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_cheesy_chicken_quesadillas.jpg?v=1', '@nada_dl', 'en', '{"calories": 365, "carbsG": 41.1, "proteinG": 22.8, "fatG": 12.2, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-fiesta-taco-casserole', seed_owner, 'Fiesta Beef Taco Casserole', 'I originally found this taco casserole recipe in a taste of home magazine. Since then, I have made this recipe at least 50 times. I love it because the ingredients list isn''t complicated and, based on the layers, I can readily remember all ingredients when I am at the store without my recipe card. I have served this for myself and had wonderful leftovers or many times I have made it for company with a nice green salad to accompany it. I hope you enjoy it as much as I do.', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g ground beef", "1 tsp taco seasoning", "2 cups refried beans", "1 cup monterey jack cheese", "Salsa", "1 medium diced green onions", "Black olives", "2 cups tomatoes", "0.75 cup corn chips"]}]'::jsonb, '[{"stepIndex": 1, "text": "Brown ground beef and drain."}, {"stepIndex": 2, "text": "Add taco seasoning and cook according to package directions, adding proper amount of water."}, {"stepIndex": 3, "text": "Put corn chips on bottom of 8x8\" dish."}, {"stepIndex": 4, "text": "Cook refried beans on stove until hot."}, {"stepIndex": 5, "text": "Add 1 cup cheese and 1 cup salsa."}, {"stepIndex": 6, "text": "Stir until combined."}, {"stepIndex": 7, "text": "Pour beans over corn chips in dish."}, {"stepIndex": 8, "text": "Add beef to top of beans."}, {"stepIndex": 9, "text": "Sprinkle remaining cheese over top."}, {"stepIndex": 10, "text": "Sprinkle green onions and black olives over cheese."}, {"stepIndex": 11, "text": "Bake in a 375 degree oven until the cheese is sufficiently melted."}, {"stepIndex": 12, "text": "Take out of oven and sprinkle chopped tomatoes on top."}, {"stepIndex": 13, "text": "Wait 1-2 minutes and then serve."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_fiesta_taco_casserole.jpg?v=1', '@aditya_eats', 'en', '{"calories": 349, "carbsG": 39.3, "proteinG": 21.8, "fatG": 11.6, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-fire-roasted-salsa', seed_owner, 'Fresh Fire-Roasted Restaurant Salsa', 'This is the best salsa recipe i''ve found so far and i''ve tried about a dozen. I got it from one of the local hospital cookbooks that are sold in my area. I changed it a bit and have been canning it for years. The reason I plant a garden is for this salsa. We would be lost without it. Hope you like it as much as we do. One of our members who is a food scientist took this salsa to work, tested the ph and found it measured under 4.0 (well within the safety limit for boiling water bath processing).', '27 min', '48 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups tomatoes", "1 medium diced onions", "0.5 tsp green peppers", "0.5 tsp jalapeno pepper", "3 cloves minced garlic", "1 tsp cumin", "0.5 tsp pepper", "1 tsp canning salt", "0.5 cup sugar", "1 tbsp vinegar", "0.5 cup tomato sauce", "0.5 cup tomato paste"]}]'::jsonb, '[{"stepIndex": 1, "text": "Mix all together and bring to a slow boil for 10 minute."}, {"stepIndex": 2, "text": "Seal in jars and cook in hot water bath for 10 minute."}, {"stepIndex": 3, "text": "This is a medium salsa."}, {"stepIndex": 4, "text": "This is also a chunky salsa so if you want a smoother salsa cut your veggies into smaller pieces."}, {"stepIndex": 5, "text": "Yields 3-6 quarts or pints."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_fire_roasted_salsa.jpg?v=1', '@maria_cocina', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-mexican-pork-carnitas', seed_owner, 'Crispy Mexican Pork Carnitas', 'I love carnitas and the pressure cooker really makes this a quick, done, deal with all the flavor still sealed in. I will never make it another way! Thanks to my friend kerry t. For the recipe back in the day!', '23 min', '42 min', 4, '[{"groupName": "Main Ingredients", "items": ["Pork butt", "1 medium diced onion", "500g low sodium chicken broth", "1 tsp cumin", "1 tsp dried chipotle powder"]}]'::jsonb, '[{"stepIndex": 1, "text": "Throw all ingredients into the pressure cooker, stir and set it on high."}, {"stepIndex": 2, "text": "Make sure there is extra liquid, you don''t want your cooker to dry out!."}, {"stepIndex": 3, "text": "Cook for 35-45 minutes depending on your cooker."}, {"stepIndex": 4, "text": "Release steam according to your cooker''s instructions."}, {"stepIndex": 5, "text": "The meat should be falling apart by now, and there should be lots of liquid left."}, {"stepIndex": 6, "text": "Drain and save the liquid, put the meat on a plate and shred it with two forks, or use a potato masher, the onion included."}, {"stepIndex": 7, "text": "Place meat on a flat roasting pan and put it under the broiler in the oven for about 15 minutes, stirring often, and adding juice from the cooker to make sure it doesn''t get too dry."}, {"stepIndex": 8, "text": "It is done when it is a bit crispy, but not burned."}, {"stepIndex": 9, "text": "Alternatively, after you shred the meat, you can heat oil in a large skillet and brown it, adding a bit of the meat juice after it is already well crispy."}, {"stepIndex": 10, "text": "Serve with pico de gallo, tortillas, rice, and any fixin''s you have on hand like guacamole, lettuce, cheese, etc."}, {"stepIndex": 11, "text": "Hint-."}, {"stepIndex": 12, "text": "For spicier carnitas, blend 3/4 cup of juice from cooking with 4 chipotles en adobo, or a fresh habenero, serrano, or jalapeno."}, {"stepIndex": 13, "text": "Pour this over the meat before you put it under the broiler."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_mexican_pork_carnitas.jpg?v=1', '@sophie_table', 'en', '{"calories": 266, "carbsG": 29.9, "proteinG": 16.6, "fatG": 8.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-loaded-burrito-bake', seed_owner, 'Cheesy Loaded Burrito Bake', 'Satisfy your craving for something different tonight. It''s good and fairly easy. This is stuff I usually have on hand too.', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g ground beef", "1 medium diced yellow onion", "1 tsp taco seasoning", "1 cup flour tortillas", "2 cups refried beans", "1 cup taco cheese", "Cream of mushroom soup", "Sour cream", "0.5 cup hot sauce"]}]'::jsonb, '[{"stepIndex": 1, "text": "Brown ground meat / turkey & onion."}, {"stepIndex": 2, "text": "Drain."}, {"stepIndex": 3, "text": "Add taco seasoning and stir in refried beans."}, {"stepIndex": 4, "text": "Mix soup and sour cream in a separate bowl."}, {"stepIndex": 5, "text": "Spread 1/2 sour cream mixture in the bottom of a casserole dish."}, {"stepIndex": 6, "text": "Tear up 3 tortillas and spread over sour cream mixture."}, {"stepIndex": 7, "text": "Put 1/2 the meat bean mixture over that."}, {"stepIndex": 8, "text": "Add a layer of cheese."}, {"stepIndex": 9, "text": "You could put some hot sauce on this now."}, {"stepIndex": 10, "text": "Repeat the layers."}, {"stepIndex": 11, "text": "Sprinkle cheese over the top and bake, uncovered, at 350°F for 20-30 minutes."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_loaded_burrito_bake.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 512, "carbsG": 57.6, "proteinG": 32.0, "fatG": 17.1, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-beef-broccoli-stirfry', seed_owner, 'Savory Beef and Broccoli Stir-Fry', 'I clipped this recipe from taste of home magazine several years ago and have found it to be the best-tasting easy beef and broccoli stir-fry. It is credited to ruth stahl. I often use charcoal chuck steak, which is very tender and lean. I also like that it doesn''t call for any unusual ingredients.', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["Cornstarch", "1 cup water", "3 cloves minced garlic powder", "Boneless round steak", "2 tbsp vegetable oil", "Broccoli florets", "1 medium diced onion", "2 tbsp reduced sodium soy sauce", "0.5 cup brown sugar", "Ground ginger", "1.5 cups cooked rice", "Toasted sesame seeds"]}]'::jsonb, '[{"stepIndex": 1, "text": "In a bowl, combine 2 tablespoons cornstarch, 2 tablespoons water and garlic powder until smooth."}, {"stepIndex": 2, "text": "Add beef and toss."}, {"stepIndex": 3, "text": "In a large skillet or wok over medium-high heat, stir-fry beef in 1 tablespoon oil until beef reaches desired doneness."}, {"stepIndex": 4, "text": "Remove and keep warm."}, {"stepIndex": 5, "text": "Stir-fry onion in remaining oil for 4-5 minutes until softened."}, {"stepIndex": 6, "text": "Add the broccoli and cook for 3 minutes until the broccoli is tender but still crisp."}, {"stepIndex": 7, "text": "Return beef to pan."}, {"stepIndex": 8, "text": "Combine soy sauce, brown sugar, ginger and remaining 1 tablespoon cornstarch and 1/2 cup water until smooth."}, {"stepIndex": 9, "text": "Add to the pan."}, {"stepIndex": 10, "text": "Cook and stir for 2 minutes."}, {"stepIndex": 11, "text": "Serve over rice and garnish with toasted sesame seeds."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_beef_broccoli_stirfry.jpg?v=1', '@chef_marco', 'en', '{"calories": 150, "carbsG": 16.9, "proteinG": 9.4, "fatG": 5.0, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-baked-chicken-teriyaki', seed_owner, 'Baked Chicken Teriyaki', 'Easy and delicious weeknight meal. The sauce thickens while cooking so prep time is at a minimum and is perfect with rice and broccoli. You can use any cut of chicken you like - just adjust the cooking time accordingly.', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["Cornstarch", "1 cup water", "0.5 cup white sugar", "0.5 cup brown sugar", "2 tbsp low sodium soy sauce", "1 tbsp cider vinegar", "1 tbsp orange juice", "3 cloves minced garlic powder", "Ground ginger", "0.5 tsp ground black pepper", "500g skinless chicken thighs"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 425 degrees f."}, {"stepIndex": 2, "text": "Combine the first 10 ingredients in a bowl."}, {"stepIndex": 3, "text": "Place chicken pieces in a lightly greased 9x13 inch baking dish."}, {"stepIndex": 4, "text": "Pour sauce over chicken and turn to thoroughly coat."}, {"stepIndex": 5, "text": "Bake in the preheated oven for 30 minutes."}, {"stepIndex": 6, "text": "Turn pieces over, and bake for another 10 minutes, until no longer pink and juices run clear."}, {"stepIndex": 7, "text": "Spoon sauce over chicken and serve."}, {"stepIndex": 8, "text": "If using bone-in chicken breasts, bake at 375 for 35-40 minutes."}, {"stepIndex": 9, "text": "If using boneless chicken breasts, bake at 375 for 20-25 minutes."}, {"stepIndex": 10, "text": "If you prefer, bring all the ingredients to a boil in a saucepan on the stove and let simmer until thick."}, {"stepIndex": 11, "text": "Brush the chicken with the resulting glaze."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_baked_chicken_teriyaki.jpg?v=1', '@elena_bakes', 'en', '{"calories": 234, "carbsG": 26.3, "proteinG": 14.6, "fatG": 7.8, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-bangkok-pad-thai', seed_owner, 'Traditional Bangkok Pad Thai', 'A native thai woman made this for a thai cooking class. This is how she learned to make it from her mother. We tasted the dish and it was great. We did not have pad thai sauce with it but she said the store bought type was fine. Vegetables or tofu may be substituted for the chicken. She noted that overcooked noodles do not stir-fry well and do not look good. If using fresh noodles, instead of dried, they will cook in less than 1 minute.', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["1.5 cups rice noodles", "500g boneless skinless chicken breasts", "3 cloves minced garlic", "Shallot", "2 large eggs", "0.5 tsp black pepper", "2 tbsp vegetable oil", "0.5 cup brown sugar", "0.5 cup oyster sauce", "0.5 cup fish sauce", "1 tbsp white vinegar", "2 tbsp soy sauce", "1 medium diced green onion", "2 cups bean sprouts", "0.75 cup roasted peanuts", "2 tbsp fresh fresh cilantro", "1 tbsp fresh lime juice", "0.5 cup paad thai sauce"]}]'::jsonb, '[{"stepIndex": 1, "text": "Boil noodles until just soft."}, {"stepIndex": 2, "text": "Drain water and place noodles in separate bowl."}, {"stepIndex": 3, "text": "Meanwhile, heat 3 tbsp oil in wok on high heat."}, {"stepIndex": 4, "text": "Add garlic, shallots, oyster sauce, chicken and stir-fry until cooked."}, {"stepIndex": 5, "text": "Move mixture to 1/2 of wok and add eggs on empty 1/2 of wok."}, {"stepIndex": 6, "text": "Cook eggs."}, {"stepIndex": 7, "text": "Mix eggs and chicken."}, {"stepIndex": 8, "text": "Add noodles, fish sauce, vinegar, soy sauce, black pepper and brown sugar, stirring quickly so that noodles do not stick together."}, {"stepIndex": 9, "text": "Stir in bean sprouts, green onion and peanuts."}, {"stepIndex": 10, "text": "Garnish with fresh cilantro and a quick squeeze of lime juice."}, {"stepIndex": 11, "text": "Serve immediately, with pad thai sauce, as desired."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_bangkok_pad_thai.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 896, "carbsG": 100.8, "proteinG": 56.0, "fatG": 29.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-wok-fried-rice', seed_owner, 'Golden Wok Egg Fried Rice', 'I never could make fried rice, it always turned out sticky and nasty. Until one night when I couldn''t sleep, I turned on the tv and watched this infomercial for cookware and they made fried rice. And what do you know, its a good recipe! Only thing good that ever came out of a infomercial, lol. Anyway my whole family loves it and have been asked for the recipe many times. If you have leftover chicken, toss it in too. I''ve also added hamburger and other veggies with good results too.', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["1.5 cups cooked rice", "Oleo", "1 medium diced onion", "Celery", "Carrots", "Frozen peas", "2 large eggs", "2 tbsp soy sauce", "0.5 tsp pepper"]}]'::jsonb, '[{"stepIndex": 1, "text": "Melt oleo in large non-stick skillet."}, {"stepIndex": 2, "text": "Add onion, celery, and carrots."}, {"stepIndex": 3, "text": "Saute until onions are transparent and carrots are crisp tender, about 5 minutes."}, {"stepIndex": 4, "text": "Add peas and cook one minute more until peas are thawed."}, {"stepIndex": 5, "text": "Push veggies to one side of skillet."}, {"stepIndex": 6, "text": "Scramble eggs in empty side of skillet after the oleo spreads from veggies."}, {"stepIndex": 7, "text": "Mix eggs into veggies and season with pepper."}, {"stepIndex": 8, "text": "Then put in small amount of rice and then."}, {"stepIndex": 9, "text": "Add soy sauce."}, {"stepIndex": 10, "text": "Then slowly mix in rice by the spoonful until all rice is added and all ingredients are well blended."}, {"stepIndex": 11, "text": "Fry until steamy hot stirring often."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_wok_fried_rice.jpg?v=1', '@nada_dl', 'en', '{"calories": 238, "carbsG": 26.8, "proteinG": 14.9, "fatG": 7.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-pork-scallion-dumplings', seed_owner, 'Pan-Fried Pork and Scallion Dumplings', 'These are easy to make and are the richest and fluffiest I have had!', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 cup all-purpose flour", "1 tsp baking powder", "1 tsp salt", "2 tbsp butter", "1 cup milk"]}]'::jsonb, '[{"stepIndex": 1, "text": "Mix together in a bowl the flour, salt and baking powder."}, {"stepIndex": 2, "text": "Bring to just a simmer in a small saucepan the butter and milk."}, {"stepIndex": 3, "text": "Add the milk mixture to the dry ingredients."}, {"stepIndex": 4, "text": "Stir with a fork or kneed by hand 2 to 3 times until the mixture just comes together."}, {"stepIndex": 5, "text": "Divide the dough into about 16 small puffy dumplings."}, {"stepIndex": 6, "text": "Roll each piece of dough into a small rough ball."}, {"stepIndex": 7, "text": "Gently lay the formed dumplings on the surface of your stew or soup."}, {"stepIndex": 8, "text": "Cover and simmer for 10 minutes."}, {"stepIndex": 9, "text": "Serve immediately."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_pork_scallion_dumplings.jpg?v=1', '@aditya_eats', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-coconut-chicken-curry', seed_owner, 'Aromatic Coconut Chicken Curry', 'Watch out or you might get pulled over for a speeding ticket in the kitchen! Ready in 20 minutes.:)', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 cup flour", "1 tsp salt", "0.5 tsp cayenne pepper", "500g boneless skinless chicken breast", "2 tbsp canola oil", "1 tsp curry powder", "1 medium diced onion", "3 cloves minced garlic", "500g chicken broth", "Golden raisin", "0.5 cup tomato paste", "2 tbsp fresh fresh cilantro", "Plain nonfat yogurt"]}]'::jsonb, '[{"stepIndex": 1, "text": "Mix together flour, salt and cayenne pepper in a plastic bag."}, {"stepIndex": 2, "text": "Add chicken in small batches, shaking to coat."}, {"stepIndex": 3, "text": "Heat oil in a large skillet over medium-high heat."}, {"stepIndex": 4, "text": "Add chicken and cook until lightly browned."}, {"stepIndex": 5, "text": "Then add curry powder and toss to coat."}, {"stepIndex": 6, "text": "Remove from pan."}, {"stepIndex": 7, "text": "Add onion and garlic to pan, adding a little more oil if necessary, and cook for 2 minutes, then add broth, raisins, and tomato paste."}, {"stepIndex": 8, "text": "Return chicken to pan and simmer uncovered for 8 minutes or until chicken is cooked through and sauce has thickened."}, {"stepIndex": 9, "text": "Garnish with cilantro and a dollop of yogurt."}, {"stepIndex": 10, "text": "Serve with quick cooking minute rice, if desired."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_coconut_chicken_curry.jpg?v=1', '@maria_cocina', 'en', '{"calories": 284, "carbsG": 31.9, "proteinG": 17.8, "fatG": 9.5, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-scallion-egg-foo-young', seed_owner, 'Crispy Scallion Egg Foo Young', 'I can''t believe I like this dish as much as I do. I was surprised. This is a variation of a rather bland scrambled egg mix that I found on the net but turning it onto an egg foo yung is really special. Add your own favorite things but this is a good start. If you add water chestnuts, ham, shrimp, pork, whatever- then you will have to adjust the cooking time. This is a basic recipe- make it your own. But an easy recipe to amend- as soon as the egg is set- then it is done! I really love this and it is so good for a family on a budget or a bachelor short on time. If you want a terrific egg foo yung sauce then try this one recipe#45270.', '5 min', '10 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups ramen noodles", "2 tbsp butter", "2 large eggs", "1 medium diced green onions", "2 tbsp sesame oil", "2 tbsp soy sauce", "1 tsp baking powder"]}]'::jsonb, '[{"stepIndex": 1, "text": "Cook ramen noodles according to package instructions for 3 minutes blah blah and drain well in a colander."}, {"stepIndex": 2, "text": "If you don''t know how to cook ramen noodles you are too stupid to cook."}, {"stepIndex": 3, "text": "Call dominos and have them deliver you a pizza."}, {"stepIndex": 4, "text": "Whisk eggs, onions, the seasoning packet, sesame oil, soy sauce, and baking powder with a fork in a small bowl and toss in the cooked ramen noodles."}, {"stepIndex": 5, "text": "Heat butter on med high heat in an 8 inch nonstick skillet."}, {"stepIndex": 6, "text": "Throw the ramen noodle / egg mixture in the skillet and cook it."}, {"stepIndex": 7, "text": "I reiterate if you don''t know to to cook ramen noodles call dominos because you are obviously, stupid."}, {"stepIndex": 8, "text": ":(."}, {"stepIndex": 9, "text": "Flip the patty over and cook the other side until the egg is set, about two more minutes."}, {"stepIndex": 10, "text": "Flip over again and cook about 1 minute more."}, {"stepIndex": 11, "text": "Serve with soy sauce if you wish or an egg foo yung sauce."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_scallion_egg_foo_young.jpg?v=1', '@sophie_table', 'en', '{"calories": 851, "carbsG": 95.7, "proteinG": 53.2, "fatG": 28.4, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-garlic-ginger-stirfry', seed_owner, 'Garlic Ginger Chicken Stir-Fry', 'Nice and simple. Prep time includes marinating time.', '46 min', '1 hr 24 min', 4, '[{"groupName": "Main Ingredients", "items": ["3 cloves minced garlic", "2 tbsp soy sauce", "1 cup water", "2 tbsp honey", "2 tbsp vegetable oil", "Cornstarch", "0.5 tsp pepper", "0.5 tsp crushed red pepper flakes", "500g boneless skinless chicken breast", "1 medium diced green onion"]}]'::jsonb, '[{"stepIndex": 1, "text": "Combine garlic, soy sauce, water, honey, 1 tablespoon oil, cornstarch and black / red pepper."}, {"stepIndex": 2, "text": "Stir chicken into marinade and mix to coat."}, {"stepIndex": 3, "text": "Cover and refrigerate at least 2 hours, stirring once to twice."}, {"stepIndex": 4, "text": "In large skillet, heat remaining oil."}, {"stepIndex": 5, "text": "Using slotted spoon, transfer chicken to skillet."}, {"stepIndex": 6, "text": "Stir-fry about 5 minutes."}, {"stepIndex": 7, "text": "Add reserved marinade."}, {"stepIndex": 8, "text": "Continue to cook and stir about 30 seconds until thickened."}, {"stepIndex": 9, "text": "Remove to platter."}, {"stepIndex": 10, "text": "Garnish with green onion."}, {"stepIndex": 11, "text": "Serve with snow peas, if desired."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_garlic_ginger_stirfry.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 277, "carbsG": 31.2, "proteinG": 17.3, "fatG": 9.2, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-buttermilk-pancakes', seed_owner, 'Fluffy Golden Buttermilk Pancakes', 'It was the fall of 1987 when pete nyhus walked into our office, just to visit. We started talking about breakfast, and he reached into a wastepaper basket and pulled out a scrap of teletype paper. He wrote out this recipe, and my family has never used pre-mix since.', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 cup flour", "0.5 cup sugar", "1 tsp salt", "1 tsp baking powder", "2 large eggs", "2 tbsp butter", "1 cup milk"]}]'::jsonb, '[{"stepIndex": 1, "text": "Mix the dry items first."}, {"stepIndex": 2, "text": "Combine the eggs and melted butter to the milk and slowly stir into the flour mixture."}, {"stepIndex": 3, "text": "Let sit at least 10 minutes while heating the pan."}, {"stepIndex": 4, "text": "These will be high, but light and fluffy --."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_buttermilk_pancakes.jpg?v=1', '@chef_marco', 'en', '{"calories": 209, "carbsG": 23.5, "proteinG": 13.1, "fatG": 7.0, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-brioche-french-toast', seed_owner, 'Golden Brioche French Toast', 'I do not remember where I got this recipe, but my husband says it tastes just as good as what he had at denny''s. I am just amazed at all of the great reviews on this recipe!! My family loves it, so I thought I would share it here and i''m so glad I did because it seems you all love it just as much!!! Thanks to all of you who have tried it!', '8 min', '14 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 large eggs", "1 cup whole milk", "1 cup flour", "0.5 cup sugar", "Vanilla", "1 tsp salt", "1 tsp cinnamon", "Texas toast thick bread", "2 tbsp butter", "0.5 cup powdered sugar", "Syrup"]}]'::jsonb, '[{"stepIndex": 1, "text": "Mix together the eggs, milk, flour, sugar, vanilla, salt& cinnamon."}, {"stepIndex": 2, "text": "Heat a large skillet, or griddle."}, {"stepIndex": 3, "text": "When the skillet is hot, add 1 tablespoon butter."}, {"stepIndex": 4, "text": "If the butter smokes, your pan is too hot."}, {"stepIndex": 5, "text": "Turn down the heat."}, {"stepIndex": 6, "text": "Dip each slice of bread into the batter for 30 seconds on each side."}, {"stepIndex": 7, "text": "Let some of the batter drip off, then put in skillet."}, {"stepIndex": 8, "text": "Cook each slice 1 1/2-2 minutes per side until each side is golden brown."}, {"stepIndex": 9, "text": "Add more butter, if necessary, to cook all of the slices."}, {"stepIndex": 10, "text": "To serve, put on plate, dust with powdered sugar."}, {"stepIndex": 11, "text": "Serve with butter & hot syrup."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_brioche_french_toast.jpg?v=1', '@elena_bakes', 'en', '{"calories": 264, "carbsG": 29.7, "proteinG": 16.5, "fatG": 8.8, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-belgian-golden-waffles', seed_owner, 'Crispy Belgian Golden Waffles', 'These waffles are super crisp on the outside, light as a feather inside and so scrumptious! Avoid removing them from the waffle iron too soon; they should be a golden brown. Enjoy!', '14 min', '26 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 cup flour", "1 tsp baking powder", "1 tsp salt", "0.5 cup sugar", "2 large eggs", "2 tbsp vegetable oil", "1 cup milk", "Vanilla"]}]'::jsonb, '[{"stepIndex": 1, "text": "Oil the waffle maker."}, {"stepIndex": 2, "text": "Sift the dry ingredients together in a large bowl."}, {"stepIndex": 3, "text": "In separate bowl, separate egg whites and beat until stiff peaks form."}, {"stepIndex": 4, "text": "In a separate bowl, mix together the egg yolks, milk, oil, and vanilla, stir slightly."}, {"stepIndex": 5, "text": "Add to dry ingredients and mix well."}, {"stepIndex": 6, "text": "Fold in egg whites."}, {"stepIndex": 7, "text": "Cook in waffle iron on medium-high heat for around 5-10 minutes."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_belgian_golden_waffles.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 636, "carbsG": 71.5, "proteinG": 39.8, "fatG": 21.2, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-crumb-banana-muffins', seed_owner, 'Streusel Crumb Banana Muffins', 'These are so good. We love the topping.', '13 min', '22 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 cup flour", "Baking soda", "1 tsp baking powder", "1 tsp salt", "Bananas", "0.5 cup sugar", "1 large egg", "2 tbsp butter", "0.5 cup brown sugar", "1 tsp cinnamon", "0.75 cup nuts"]}]'::jsonb, '[{"stepIndex": 1, "text": "In a large bowl, mix the flour, baking soda, baking powder, and salt."}, {"stepIndex": 2, "text": "Mix bananas, sugar, egg and melted butter."}, {"stepIndex": 3, "text": "Stir into dry mixture until thoroughly combined, then stop mixing."}, {"stepIndex": 4, "text": "Fill muffin cups 3/4 full."}, {"stepIndex": 5, "text": "Combine brown sugar, flour, and cinnamon topping ingredients."}, {"stepIndex": 6, "text": "Cut in cold butter until crumbly."}, {"stepIndex": 7, "text": "Sprinkle over muffins."}, {"stepIndex": 8, "text": "Bake at 375 degrees fahrenheit for about 20 minutes, until muffins test done."}, {"stepIndex": 9, "text": "Cool in pan for 10 minutes."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_crumb_banana_muffins.jpg?v=1', '@nada_dl', 'en', '{"calories": 220, "carbsG": 24.8, "proteinG": 13.8, "fatG": 7.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-bakery-blueberry-muffins', seed_owner, 'Fresh Bakery Blueberry Muffins', 'Very tasty and sweet.', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "0.5 cup granulated sugar", "2 large eggs", "Vanilla", "1 tsp baking powder", "1 tsp salt", "1 cup all-purpose flour", "1 cup milk", "Fresh blueberries", "Lemon zest", "0.75 cup ground nutmeg"]}]'::jsonb, '[{"stepIndex": 1, "text": "Heat oven to 375."}, {"stepIndex": 2, "text": "Grease 18 regular-size muffin cups."}, {"stepIndex": 3, "text": "In bowl, mix butter until creamy."}, {"stepIndex": 4, "text": "Add sugar and beat until pale and fluffy."}, {"stepIndex": 5, "text": "Add eggs one at a time, beating after each."}, {"stepIndex": 6, "text": "Beat in vanilla, baking powder and salt."}, {"stepIndex": 7, "text": "With spoon, fold in half of flour then half of milk into batter."}, {"stepIndex": 8, "text": "Repeat."}, {"stepIndex": 9, "text": "Fold in blueberries."}, {"stepIndex": 10, "text": "Spoon into muffin cups and sprinkle topping onto each muffin."}, {"stepIndex": 11, "text": "Bake 15 to 20 minutes, until golden brown and springy to touch."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_bakery_blueberry_muffins.jpg?v=1', '@aditya_eats', 'en', '{"calories": 256, "carbsG": 28.8, "proteinG": 16.0, "fatG": 8.5, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-garden-herb-frittata', seed_owner, 'Garden Vegetable and Herb Frittata', 'This looks so nice when it''s done, with the cheese bubbling on top. And it tastes as good as it looks! You could also use left over cooked potatoes, sliced, instead of cooking them especially for this dish.', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups potatoes", "Bacon", "1 medium diced onion", "Mushrooms", "2 large eggs", "1 cup shredded cheddar cheese", "Dill", "1 tsp salt and pepper", "2 tbsp olive oil"]}]'::jsonb, '[{"stepIndex": 1, "text": "Boil potatoes in a small saucepan until tender."}, {"stepIndex": 2, "text": "Meanwhile, heat oil in a pan and fry the onions, mushrooms and bacon until onions are clear and bacon is cooked."}, {"stepIndex": 3, "text": "Drain potatoes and put into frying pan, cooking for another 2 minutes."}, {"stepIndex": 4, "text": "Make sure ingredients are spread evenly over the pan and then pour eggs evenly over the base."}, {"stepIndex": 5, "text": "Season with herbs, salt and pepper, to taste."}, {"stepIndex": 6, "text": "Let cook for 2 minutes or until eggs start to set."}, {"stepIndex": 7, "text": "Sprinkle cheese over the top and bake under a grill until eggs are cooked and cheese is bubbling and brown."}, {"stepIndex": 8, "text": "Serve with a tall glass of orange juice and some toast."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_garden_herb_frittata.jpg?v=1', '@maria_cocina', 'en', '{"calories": 387, "carbsG": 43.5, "proteinG": 24.2, "fatG": 12.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-ham-cheddar-omelet', seed_owner, 'Baked Ham and Cheddar Omelet Roll', 'This is an easy way to serve omelets. In our house, it takes me forever to make breakfast on the stove top! Baking this is soooo much easier. Feel free to add or subtract to suit your tastes (bacon, sausage, onions, peppers, etc.)', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 large eggs", "1 cup milk", "1 cup all-purpose flour", "1 tsp salt", "0.5 tsp black pepper", "Cooked ham", "1 cup shredded sharp cheddar cheese"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 450 degrees."}, {"stepIndex": 2, "text": "Beat eggs and milk until fluffy."}, {"stepIndex": 3, "text": "Add flour, salt and pepper and beat or whisk until smooth."}, {"stepIndex": 4, "text": "Pour into a buttered or greased 9 x 13 baking dish or pan."}, {"stepIndex": 5, "text": "Bake for 10 - 15 minutes or until eggs are just about set."}, {"stepIndex": 6, "text": "Sprinkle with chopped ham or lay slices of ham evenly on top."}, {"stepIndex": 7, "text": "Sprinkle with cheese."}, {"stepIndex": 8, "text": "Bake for about 5 minutes more or until cheese is melted."}, {"stepIndex": 9, "text": "Starting at short side, roll up omelet while still in pan."}, {"stepIndex": 10, "text": "Place seam side down on serving dish."}, {"stepIndex": 11, "text": "Cut into slices."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_ham_cheddar_omelet.jpg?v=1', '@sophie_table', 'en', '{"calories": 409, "carbsG": 46.0, "proteinG": 25.6, "fatG": 13.6, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-strawberry-cream-crepes', seed_owner, 'Sweet Crepes with Fresh Strawberry Cream', 'Yummy!! This recipe will knock the socks off any guest! This recipe my mother originally found out of a cookbook, but unfortunately I do not know which. This works well with both frozen and fresh strawberries. I''d imagine almost any fruit could be substituted as well. (prep time does not include chilling of strawberries).', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["Strawberries", "0.5 cup sugar", "1 cup cream cheese", "0.5 cup powdered sugar", "Vanilla", "2 large eggs", "1 cup milk", "2 tbsp oil", "1 cup flour", "1 tsp salt"]}]'::jsonb, '[{"stepIndex": 1, "text": "To make strawberry cream: combine the strawberries and sugar and chill, anywhere from an hour to overnight."}, {"stepIndex": 2, "text": "Drain excess water from strawberries and sugar."}, {"stepIndex": 3, "text": "In mixing bowl blend cream cheese and powdered sugar until smooth."}, {"stepIndex": 4, "text": "Stir in reserved strawberries."}, {"stepIndex": 5, "text": "To make dessert crepes: beat eggs."}, {"stepIndex": 6, "text": "Add remaining ingredients."}, {"stepIndex": 7, "text": "Heat pan over med-high heat."}, {"stepIndex": 8, "text": "When a few drops of water sprinkled on the pan bounces is about the right temperature."}, {"stepIndex": 9, "text": "Pour about 1/8 c of batter into pan, tilting to spread evenly."}, {"stepIndex": 10, "text": "When the crepe has turned a light brown color you may or may not want to turn to brown other side."}, {"stepIndex": 11, "text": "Turn to brown other side if batter has not set."}, {"stepIndex": 12, "text": "Fill crepes with strawberry cream."}, {"stepIndex": 13, "text": "May serve immedietly or chills well in the refrigerator."}, {"stepIndex": 14, "text": "Before serving I usually sprinkle a little extra powdered sugar on the crepes."}, {"stepIndex": 15, "text": "The dessert crepe receipe will also work well with many other fillings."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_strawberry_cream_crepes.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 206, "carbsG": 23.2, "proteinG": 12.9, "fatG": 6.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-cinnamon-banana-bread', seed_owner, 'Classic Moist Cinnamon Banana Bread', 'You''ll never need another banana bread recipe ever again!', '23 min', '42 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "0.5 cup granulated sugar", "2 large eggs", "Bananas", "1 cup all-purpose flour", "Baking soda", "1 tsp salt", "Vanilla"]}]'::jsonb, '[{"stepIndex": 1, "text": "Remove odd pots and pans from oven."}, {"stepIndex": 2, "text": "Preheat oven to 350/180."}, {"stepIndex": 3, "text": "Cream together butter and sugar."}, {"stepIndex": 4, "text": "Add eggs and crushed bananas."}, {"stepIndex": 5, "text": "Combine well."}, {"stepIndex": 6, "text": "Sift together flour, soda and salt."}, {"stepIndex": 7, "text": "Add to creamed mixture."}, {"stepIndex": 8, "text": "Add vanilla."}, {"stepIndex": 9, "text": "Mix just until combined."}, {"stepIndex": 10, "text": "Do not overmix."}, {"stepIndex": 11, "text": "Pour into greased and floured loaf pan."}, {"stepIndex": 12, "text": "Bake at 350/180 for 55 minutes."}, {"stepIndex": 13, "text": "Keeps well, refrigerated."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_cinnamon_banana_bread.jpg?v=1', '@chef_marco', 'en', '{"calories": 272, "carbsG": 30.6, "proteinG": 17.0, "fatG": 9.1, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-fudgy-chocolate-brownies', seed_owner, 'Fudgy Dark Chocolate Brownies', 'This is the best brownie recipe i''ve ever used and i''ve used several!', '14 min', '26 min', 4, '[{"groupName": "Main Ingredients", "items": ["1 tsp cocoa powder", "Shortening", "0.5 cup sugar", "2 large eggs", "Vanilla", "1 cup flour", "1 tsp baking powder", "1 tsp salt", "0.75 cup walnuts"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 350 degrees."}, {"stepIndex": 2, "text": "Grease a 9x13\" pan."}, {"stepIndex": 3, "text": "Melt shortening in a large saucepan over low heat, then stir in cocoa."}, {"stepIndex": 4, "text": "Remove from heat."}, {"stepIndex": 5, "text": "Mix in sugar and vanilla then mix in eggs one at a time."}, {"stepIndex": 6, "text": "Stir in remaining ingredients then stir in nuts."}, {"stepIndex": 7, "text": "Bake for 30 minutes."}, {"stepIndex": 8, "text": "Cool completely, before cutting into 2x2\" squares."}, {"stepIndex": 9, "text": "I have read all the great reviews and learned from them, thank you all."}, {"stepIndex": 10, "text": "Now I line my pan with buttered alumunin foil or parchment paper."}, {"stepIndex": 11, "text": "This works very well."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_fudgy_chocolate_brownies.jpg?v=1', '@elena_bakes', 'en', '{"calories": 174, "carbsG": 19.6, "proteinG": 10.9, "fatG": 5.8, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-cheesecake-strawberries', seed_owner, 'Cheesecake Stuffed Strawberries', 'Omg.. These are like heaven in your mouth! Talk about great taste sensations... I made these for one of my cooking and recipe events that I hold monthly, and these were a huge hit... A must try for sure! You can use low fat cream cheese to make these lighter if you like. You can also dip the ends with any kind of finely chopped nuts, mini chocolate chips, graham cracker crumbs, sprinkles, or dip the ends in chocolate or drizzle with chocolate. You might even try adding some cocoa powder to the cream cheese and make it a chocolate filling. The sky is the limit here, just use your imagination!', '11 min', '19 min', 4, '[{"groupName": "Main Ingredients", "items": ["Strawberries", "1 cup cream cheese", "Vanilla", "0.5 cup confectioners'' sugar", "Almonds"]}]'::jsonb, '[{"stepIndex": 1, "text": "Place cream cheese in a bowl, and microwave for 30 seconds, so that it''s soft."}, {"stepIndex": 2, "text": "Whip together the cream cheese, vanilla, and sugar."}, {"stepIndex": 3, "text": "In the center of each strawberry, using a sharp knife, make a hole in each one, as deep as you can without going out the bottom."}, {"stepIndex": 4, "text": "Spoon or pipe the filling into each hole."}, {"stepIndex": 5, "text": "Dip cheesecake end of strawberry into chopped almonds, making sure you completely cover the cheesecake filling with the nuts."}, {"stepIndex": 6, "text": "Lay strawberries in a pretty serving dish."}, {"stepIndex": 7, "text": "Sprinkle with any leftover nuts around the dish."}, {"stepIndex": 8, "text": "Chill, and serve."}, {"stepIndex": 9, "text": "Makes 24 servings."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_cheesecake_strawberries.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-soft-chocolate-chip-cookies', seed_owner, 'Chewy Soft-Batch Chocolate Chip Cookies', 'A soft & chewy cookie. One of my favorites', '9 min', '14 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "0.5 cup sugar", "0.5 cup light brown sugar", "2 large eggs", "Vanilla", "1 cup flour", "Baking soda", "Instant vanilla pudding", "1 cup milk chocolate chips", "0.75 cup walnuts"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 375 degrees."}, {"stepIndex": 2, "text": "Mix butter, sugar, brown sugar, vanilla and eggs together until creamy."}, {"stepIndex": 3, "text": "Add the remaining ingredients and blend well."}, {"stepIndex": 4, "text": "Bake until lightly browned."}, {"stepIndex": 5, "text": "Store in an air tight container."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_soft_chocolate_chip_cookies.jpg?v=1', '@nada_dl', 'en', '{"calories": 221, "carbsG": 24.9, "proteinG": 13.8, "fatG": 7.4, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-almost-apple-pie', seed_owner, 'Almost Apple Pie', 'While this recipe is good any time it is the first one requested when the fall apples ripen. It was passed to me by a family member. The recipe calls for an 8x8 deep baking pan. Family member uses a corning ware casserole dish for the baking which makes for a lovely dessert. I often bake it in a pie plate and when cool slice and serve as you would pie. Using white sugar in the crumb crust has it so tasting like pastry. Quick and easy to make. Note - recently found this recipe from an old family cookbook is called aunties ''old fashioned crumb cake'' and calls for baking in a 425 oven for 40 to 50 minutes or until brown and crisp. Just made it and found baked at the higher temperature it very like an apple crisp - an absolutely delicious version of almost apple pie and another great apple dessert to serve family and friends. Ovens vary - I used a slightly lower oven temp.', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["Margarine", "0.5 cup white sugar", "1 cup flour", "Sliced apples", "1 tsp cinnamon"]}]'::jsonb, '[{"stepIndex": 1, "text": "Whisk the crumb mixture together and pat half the crumb mix into an 8x8 baking pan."}, {"stepIndex": 2, "text": "Slice apples into a large bowl, add the dry ingredients, mix gently and place filling over the crumb base."}, {"stepIndex": 3, "text": "Put the remaining crumbs over the apples and pat in place."}, {"stepIndex": 4, "text": "Bake in a 350 oven 40 to 50 minutes or till nicely colored, times vary from oven to oven."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_almost_apple_pie.jpg?v=1', '@aditya_eats', 'en', '{"calories": 435, "carbsG": 48.9, "proteinG": 27.2, "fatG": 14.5, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-cinnamon-snickerdoodles', seed_owner, 'Cinnamon Sugar Snickerdoodles', 'These snickerdoodle cookies are so delicious, and they have the best texture. They are so fast to put together too! I actually got it from an old recipe that my great grandma had clipped out of a newspaper. Grandma always knows best!', '9 min', '16 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "0.5 cup sugar", "2 large eggs", "1 cup flour", "Cream of tartar", "Baking soda", "1 tsp salt", "1 tsp cinnamon", "Vanilla extract"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 350°F."}, {"stepIndex": 2, "text": "Mix softened butter, 1 1/2 cups sugar, 1tps of vanilla extract and eggs thoroughly in a large bowl."}, {"stepIndex": 3, "text": "Combine flour, cream of tartar, baking soda and salt in a separate bowl."}, {"stepIndex": 4, "text": "Blend dry ingredients into butter mixture."}, {"stepIndex": 5, "text": "Chill dough, and chill an ungreased cookie sheet for about 10-15 minutes in the fridge."}, {"stepIndex": 6, "text": "Meanwhile, mix 3 tablespoons sugar, and 3 teaspoons cinnamon in a small bowl."}, {"stepIndex": 7, "text": "Scoop 1 inch globs of dough into the sugar / cinnamon mixture."}, {"stepIndex": 8, "text": "Coat by gently rolling balls of dough in the sugar mixture."}, {"stepIndex": 9, "text": "Place on chilled ungreased cookie sheet, and bake 10 minutes."}, {"stepIndex": 10, "text": "Remove from pan immediately."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_cinnamon_snickerdoodles.jpg?v=1', '@maria_cocina', 'en', '{"calories": 182, "carbsG": 20.5, "proteinG": 11.4, "fatG": 6.1, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-peanut-butter-cookies', seed_owner, 'Old-Fashioned Peanut Butter Cookies', 'This is my husband''s grandmother''s recipe that is cherished by the family. They are the best cookie that melts in your mouth. They don''t have the normal peanut butter fork crossing...but more of a crackled sugar type cookie... My husband comes from a huge family - and these are one of the cherished recipes!!', '10 min', '17 min', 4, '[{"groupName": "Main Ingredients", "items": ["0.5 cup brown sugar", "0.5 cup white sugar", "2 tbsp butter flavor crisco", "2 tbsp creamy peanut butter", "1 tsp salt", "2 large eggs", "Vanilla", "Baking soda", "1 cup flour"]}]'::jsonb, '[{"stepIndex": 1, "text": "Cream together the sugars, crisco, peanut butter."}, {"stepIndex": 2, "text": "Add the eggs and vanilla."}, {"stepIndex": 3, "text": "Sift the dry ingredients together and add gradually until blended well."}, {"stepIndex": 4, "text": "Roll into tablespoon size balls."}, {"stepIndex": 5, "text": "Roll cookie dough balls into sugar."}, {"stepIndex": 6, "text": "Place on cookie sheets- do not mash with fork in normal \"peanut butter cookie\" fashion!."}, {"stepIndex": 7, "text": "Bake at 350 oven for 11-13 minutes."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_peanut_butter_cookies.jpg?v=1', '@sophie_table', 'en', '{"calories": 167, "carbsG": 18.8, "proteinG": 10.4, "fatG": 5.6, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-whipped-shortbread', seed_owner, 'Melt-in-Your-Mouth Whipped Shortbread', 'These are very easy to make shortbread cookies. They are so good that they melt in your mouth, you hardly have to chew them. I have been making them for over 35 years.', '12 min', '20 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "1 cup all-purpose flour", "0.5 cup icing sugar", "Vanilla extract", "Red maraschino cherry", "Green maraschino cherry"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 350 degrees f."}, {"stepIndex": 2, "text": "In a mixing bowl and using an electric mixer, combine butter, flour, icing sugar and vanilla extract."}, {"stepIndex": 3, "text": "Mix until mixture is a smooth consistency."}, {"stepIndex": 4, "text": "Prepare cookie sheets with parchment paper."}, {"stepIndex": 5, "text": "Spoon out dough onto parchment lined cookie sheets by teaspoonfuls or by tablespoons for larger cookies, spacing about 2 inches apart."}, {"stepIndex": 6, "text": "Cut maraschino cherries into quarters and place one piece in the middle of each cookie, alternating with red and green cherries."}, {"stepIndex": 7, "text": "Bake in preheated 350°F oven for 13 to 15 minutes or until bottom of cookies are lightly browned, do not overbake."}, {"stepIndex": 8, "text": "Remove from oven and let cool on cookie sheet for about 5 minutes."}, {"stepIndex": 9, "text": "Transfer onto wire racks to finish cooling."}, {"stepIndex": 10, "text": "Store in a container with a lid and separate each layer with wax paper."}, {"stepIndex": 11, "text": "Use sprinkles, half an almond or half a cashew or chocolate to the top of the cookies before baking."}, {"stepIndex": 12, "text": "A thumbprint in the cookie, filled with your choice of jam is very tasty."}, {"stepIndex": 13, "text": "It has been suggested that the cookies be refrigerated for at least 1/2 hour before baking for a different texture."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_whipped_shortbread.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-golden-chicken-pot-pie', seed_owner, 'Homestyle Golden Chicken Pot Pie', 'This chicken pot pie recipe takes a little time, but it is well worth it!! This is an all-time favorite in our family. Great on a cold winter day.', '37 min', '1 hr 8 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups potato", "1 medium diced onion", "Celery", "Carrot", "Margarine", "1 cup all-purpose flour", "500g chicken broth", "Half-and-half", "1 tsp salt", "0.5 tsp pepper", "500g chicken", "Pie crusts"]}]'::jsonb, '[{"stepIndex": 1, "text": "Preheat oven to 400°F."}, {"stepIndex": 2, "text": "Saute onion, celery, carrots and potatoes in margarine for 10 minutes."}, {"stepIndex": 3, "text": "Add flour to sauteed mixture, stirring well, cook one minute stirring constantly."}, {"stepIndex": 4, "text": "Combine broth and half and half."}, {"stepIndex": 5, "text": "Gradually stir into vegetable mixture."}, {"stepIndex": 6, "text": "Cook over medium heat stirring constantly until thickened and bubbly."}, {"stepIndex": 7, "text": "Stir in salt and pepper."}, {"stepIndex": 8, "text": "Add chicken and stir well."}, {"stepIndex": 9, "text": "Pour into shallow 2 quart casserole dish and top with pie shells."}, {"stepIndex": 10, "text": "Cut slits to allow steam to escape."}, {"stepIndex": 11, "text": "Bake for 40-50 minutes or until pastry is golden brown and filling is bubbly and cooked through."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_golden_chicken_pot_pie.jpg?v=1', '@chef_marco', 'en', '{"calories": 538, "carbsG": 60.5, "proteinG": 33.6, "fatG": 17.9, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-bbq-pork-ribs', seed_owner, 'Slow-Baked Fall-Off-The-Bone BBQ Ribs', 'After not being able to find restaurant ribs that satified my hot sweet appetite, I carefully attempted various combinations of flavors until I found one that I and my family thought was perfect. Hope you enjoy them too.', '25 min', '45 min', 4, '[{"groupName": "Main Ingredients", "items": ["Pork back ribs", "2 tbsp honey", "1 tsp paprika", "1 tsp chili powder", "3 cloves minced garlic powder", "1 tsp old bay seasoning", "1 medium diced onion powder", "1 tsp celery salt", "0.5 cup dark brown sugar", "0.5 tsp fresh ground pepper", "1 medium diced onion", "0.5 cup barbecue sauce", "0.5 cup white sugar"]}]'::jsonb, '[{"stepIndex": 1, "text": "Place all ingredients together in large roasting pan."}, {"stepIndex": 2, "text": "Cut ribs apart for easier serving."}, {"stepIndex": 3, "text": "Mix together making sure to coat all ribs with this semi-dry paste."}, {"stepIndex": 4, "text": "Spread ribs out evenly on bottom of pan."}, {"stepIndex": 5, "text": "Cover lightly with foil."}, {"stepIndex": 6, "text": "Bake at 375 degrees for approximately 1 hour."}, {"stepIndex": 7, "text": "Turning or stirring occasionally."}, {"stepIndex": 8, "text": "You can use broiler for these ribs, just watch more closely, and adjust cooking time."}, {"stepIndex": 9, "text": "These ribs are also great finished on the grill for a few minutes on each side."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_bbq_pork_ribs.jpg?v=1', '@elena_bakes', 'en', '{"calories": 1245, "carbsG": 140.1, "proteinG": 77.8, "fatG": 41.5, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-four-cheese-macaroni', seed_owner, 'Creamy Four-Cheese Macaroni and Cheese', 'This is the recipe I have been using for macaroni and cheese since the beginning of time! Truly a classic and a staple on our family table. I hope you enjoy it as much as we do. A great side dish to be served with my meatloaf barbecue style!', '16 min', '29 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp butter", "1 cup flour", "1 tsp salt", "Dry mustard", "0.5 tsp pepper", "1 cup milk", "1 cup shredded cheddar cheese", "Elbow macaroni"]}]'::jsonb, '[{"stepIndex": 1, "text": "Melt butter in medium saucepan."}, {"stepIndex": 2, "text": "Stir in flour, salt, mustard and pepper until smooth."}, {"stepIndex": 3, "text": "Remove from heat and gradually stir in milk until smooth."}, {"stepIndex": 4, "text": "Stirring constantly, cook over medium heat until thickened."}, {"stepIndex": 5, "text": "Remove from heat."}, {"stepIndex": 6, "text": "Stir in 1 1/2 cups cheese until melted."}, {"stepIndex": 7, "text": "Combine cheese mixture with macaroni in greased 2 quart casserole."}, {"stepIndex": 8, "text": "Sprinkle remaining cheese on top."}, {"stepIndex": 9, "text": "Bake in 375 degree oven for 25 minutes or until lightly browned."}, {"stepIndex": 10, "text": "Makes 6 servings."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_four_cheese_macaroni.jpg?v=1', '@streetfood_ken', 'en', '{"calories": 420, "carbsG": 47.2, "proteinG": 26.2, "fatG": 14.0, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-boston-clam-chowder', seed_owner, 'Creamy Boston Clam Chowder', 'This is the best chowder i''ve ever had. I''ve had chowder at legal seafoods in boston, which I have to say is good, but mine is better! If you like thick chowder, you''ll love this one!!', '27 min', '48 min', 4, '[{"groupName": "Main Ingredients", "items": ["Bacon", "1 medium diced onion", "Baby clams", "2 cups potatoes", "Cream of celery soup", "1 cup heavy cream", "1 cup milk", "2 tbsp butter", "Dried dill weed"]}]'::jsonb, '[{"stepIndex": 1, "text": "Add bacon to sauce pan and cook on medium low heat until crispy."}, {"stepIndex": 2, "text": "Add onion and cook until translucent."}, {"stepIndex": 3, "text": "Add clam juice from both cans."}, {"stepIndex": 4, "text": "Add potatoes."}, {"stepIndex": 5, "text": "Cook and cover until potatoes are fork tender, about 15-20 minutes."}, {"stepIndex": 6, "text": "Stir occasionally so potatoes won''t stick."}, {"stepIndex": 7, "text": "Add clams, soup, cream, milk, and dill weed."}, {"stepIndex": 8, "text": "Stir together."}, {"stepIndex": 9, "text": "Add butter and let melt into the chowder."}, {"stepIndex": 10, "text": "Cook for about 30-45 minutes or until thickened."}, {"stepIndex": 11, "text": "Stir occasionally."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_boston_clam_chowder.jpg?v=1', '@nada_dl', 'en', '{"calories": 753, "carbsG": 84.7, "proteinG": 47.1, "fatG": 25.1, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-slow-simmered-beef-stew', seed_owner, 'Hearty Slow-Simmered Beef Stew', 'I originally found this recipe at recipe goldmine but have added and subtracted after trial and error. The original recipe called for a 10 oz pkg of frozen peas to be added during the last 15 minutes of cooking. I usually add a little rosemary and cayenne. Can add the spices you wish. This is very good!', '56 min', '1 hr 44 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g beef stew meat", "1 cup flour", "1 tsp salt", "0.5 tsp pepper", "2 tbsp vegetable oil", "1 medium diced onion", "Carrot", "Celery", "2 tbsp dried parsley", "Thyme", "500g beef broth", "2 cups potatoes", "Carrots", "1 medium diced onions"]}]'::jsonb, '[{"stepIndex": 1, "text": "Put flour, salt and pepper in a large ziploc bag."}, {"stepIndex": 2, "text": "Heat oil over medium heat in a large dutch oven."}, {"stepIndex": 3, "text": "Place meat in bag with the flour and shake until well coated."}, {"stepIndex": 4, "text": "Shake off meat pieces and add them to the oil and stir until slightly browned, add remaining flour from the bag and the finely chopped onion."}, {"stepIndex": 5, "text": "Stir until well browned."}, {"stepIndex": 6, "text": "Add finely chopped carrot and next 4 ingredients."}, {"stepIndex": 7, "text": "Cover and cook over low heat for 1 1/2 hours."}, {"stepIndex": 8, "text": "Add diced potatoes, carrots, and onions, cook for another 45 minutes or until potatoes are tender."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_slow_simmered_beef_stew.jpg?v=1', '@aditya_eats', 'en', '{"calories": 473, "carbsG": 53.2, "proteinG": 29.6, "fatG": 15.8, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-sweet-spicy-chili', seed_owner, 'Smoky Honey Sweet and Spicy Chili', 'Sinfully sweet, tastefully spicy--so delicious I ate 4 bowls in less than 20 hours--2 for dinner then 2 for lunch the next day! Go on, try it. You''ll love it up.', '18 min', '32 min', 4, '[{"groupName": "Main Ingredients", "items": ["500g ground beef", "1 medium diced sweet onion", "3 cloves minced garlic clove", "0.5 tsp green bell pepper", "0.5 tsp jalapeno peppers", "2 cups chili beans", "2 cups diced tomatoes", "1 tsp chili powder", "1 tsp cumin", "Thyme", "1 tsp salt", "1 tsp accent seasoning", "1 tsp cinnamon", "2 tbsp honey"]}]'::jsonb, '[{"stepIndex": 1, "text": "Crumble ground beef in large pan."}, {"stepIndex": 2, "text": "Add accent flavor enhancer."}, {"stepIndex": 3, "text": "Brown ground beef."}, {"stepIndex": 4, "text": "Add onion, green pepper, and garlic."}, {"stepIndex": 5, "text": "Cook until onion is translucent / brown."}, {"stepIndex": 6, "text": "Drain oil."}, {"stepIndex": 7, "text": "Add tomatoes, jalapeo peppers, chili beans, chili powder, cumin, thyme, salt and cinnamon."}, {"stepIndex": 8, "text": "Stir and simmer on low for at least 25 minutes."}, {"stepIndex": 9, "text": "Add honey."}, {"stepIndex": 10, "text": "Stir again."}, {"stepIndex": 11, "text": "Serve alone, over rice, or spaghetti."}, {"stepIndex": 12, "text": "Serve with cheese & crackers is a must!."}, {"stepIndex": 13, "text": "Oh--great with corn bread as well!."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_sweet_spicy_chili.jpg?v=1', '@maria_cocina', 'en', '{"calories": 624, "carbsG": 70.2, "proteinG": 39.0, "fatG": 20.8, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-mediterranean-greek-salad', seed_owner, 'Crisp Mediterranean Greek Village Salad', 'Be prepared for the best greek salad on the planet! --- plan ahead the dressing needs at least 2 or more hours to blend the flavors, I sometimes add in 1/4 cup parmesan cheese to the dressing for a more cheesy dressing, all amounts may be adjusted to taste ---- to marinade the salad allow to sit at room temperature before serving, see bottom of instructions --- you will find this and many more of my recipes posted here http://kittencalskitchen.com/2009/04/13/kittens-famous-greek-salad/ ---also see my recipe #359292', '5 min', '10 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 tbsp olive oil", "1 tbsp lemon, juice of", "2 tbsp dried oregano", "3 cloves minced garlic", "2 tbsp dried basil", "1 tbsp red wine vinegar", "1 tsp salt", "0.5 cup sugar", "0.5 tsp fresh ground black pepper", "Romaine lettuce", "2 cups plum tomatoes", "English cucumber", "1 medium diced red onion", "0.5 tsp green bell pepper", "1 cup feta cheese", "Kalamata olive"]}]'::jsonb, '[{"stepIndex": 1, "text": "For the dressing."}, {"stepIndex": 2, "text": "In a processor or use a wire whisk process / whisk the olive oil with lemon juice, 2 teaspoons dried oregano, garlic, dried, basil, red wine vinegar, salt and sugar until smooth."}, {"stepIndex": 3, "text": "Season with black pepper."}, {"stepIndex": 4, "text": "Chill in fridge for a couple of hours before using to blend flavors."}, {"stepIndex": 5, "text": "Place the salad ingredients in a large bowl."}, {"stepIndex": 6, "text": "Pour dressing over."}, {"stepIndex": 7, "text": "Toss to combine."}, {"stepIndex": 8, "text": "If desired allow the salad to sit at room temperature for 20 minutes before serving, or you can refrigerate for 1 hour."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_mediterranean_greek_salad.jpg?v=1', '@sophie_table', 'en', '{"calories": 489, "carbsG": 55.0, "proteinG": 30.6, "fatG": 16.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-garlic-caesar-salad', seed_owner, 'Classic Creamy Garlic Caesar Salad', 'I developed this dressing years ago, and I can honestly say that you won''t be able to keep your spoon out of the fridge for a taste, it is *that* good! --- although I do think the dressing is better with the anchovy it can certainly be made without them. In a pinch I have even substituted buttermilk for the half and half cream, just use about the same amount --- this dressing gets stronger with refrigeration time so a small amount of fresh garlic goes a long way! ---- usually one recipe without doubling is perfect for one large romaine lettuce, if you are serving a large crowd of people you might want to double -- salad dressing will not work for this use *only* mayonnaise, I find hellman''s brand mayonnaise works the best and for the perfect companion to this salad see my recipe#125034-------------lower-fat option use reduced fat mayonnaise and fat-free half and half or low-fat milk --- also see my recipe#66596', '5 min', '10 min', 4, '[{"groupName": "Main Ingredients", "items": ["Head romaine lettuce", "3 cloves minced garlic-flavored croutons", "0.5 cup grated parmesan cheese", "0.5 tsp black pepper", "Anchovy fillets", "3 cloves minced fresh garlic", "Mayonnaise", "Half-and-half cream", "1 tbsp lemon juice", "Dijon mustard", "1 tsp salt and pepper", "0.5 cup worcestershire sauce", "2 tbsp buttermilk"]}]'::jsonb, '[{"stepIndex": 1, "text": "In a small 2-cup mini food processor, process / mince the anchovy fillets and garlic together until finely minced."}, {"stepIndex": 2, "text": "Add in the remaining ingredients, and process for 30 seconds, or more until well mixed."}, {"stepIndex": 3, "text": "Adjust seasonings to taste."}, {"stepIndex": 4, "text": "Thin with buttermilk for a thinner consistency if desired."}, {"stepIndex": 5, "text": "Store in fridge, covered in a glass container for 3 or more hours before using."}, {"stepIndex": 6, "text": "Toss desired amount of dressing with romaine lettuce and croutons."}, {"stepIndex": 7, "text": "Sprinkle with more grated parmesan cheese if desired."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_garlic_caesar_salad.jpg?v=1', '@tasty_chronicles', 'en', '{"calories": 391, "carbsG": 44.0, "proteinG": 24.4, "fatG": 13.0, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-cucumber-tzatziki', seed_owner, 'Cool Cucumber Garlic Tzatziki Dip', 'This well-known greek ''meze'' is good in so many different ways...read on...', '5 min', '10 min', 4, '[{"groupName": "Main Ingredients", "items": ["Sour cream", "English cucumber", "3 cloves minced garlic", "2 tbsp olive oil", "1 tbsp red wine vinegar", "Fresh dill", "1 tsp salt"]}]'::jsonb, '[{"stepIndex": 1, "text": "Just mix everything up together until it is all blended and the oil has emulsified into the yoghurt / sour cream."}, {"stepIndex": 2, "text": "Taste for seasoning, and add salt if you think necessary."}, {"stepIndex": 3, "text": "Put in a resealable container."}, {"stepIndex": 4, "text": "Allow to ''sit'' in the refrigerator for at least 2-3 hours before using to allow the flavors to come out."}, {"stepIndex": 5, "text": "This wonderful meze is used to counterpoint rich, bbq''d meats, but can be used in more diverse ways."}, {"stepIndex": 6, "text": "Place a small plate full on your dinner table for people to scoop up small amounts onto their bread."}, {"stepIndex": 7, "text": "Fry up some zucchini or eggplant slices and serve with a dollop of tzatziki on top."}, {"stepIndex": 8, "text": "Use as a salad dressing."}, {"stepIndex": 9, "text": "A dip for crudites."}, {"stepIndex": 10, "text": "This eliminates even more water."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_cucumber_tzatziki.jpg?v=1', '@chef_marco', 'en', '{"calories": 132, "carbsG": 14.8, "proteinG": 8.2, "fatG": 4.4, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone'),
        ('recipe-roasted-pepper-hummus', seed_owner, 'Roasted Red Pepper and Feta Hummus', 'Middle eastern style spread for pita bread. This recipe is very tasty and easy to make. This is a very popular dish in this region. The base is usually chickpeas and tahini, but the flavor added to the base vary widely from one chef to the next. Tahini is a sesame paste, you can usually find it in the mediterranean section of your grocery store.', '7 min', '13 min', 4, '[{"groupName": "Main Ingredients", "items": ["2 cups garbanzo beans", "0.5 tsp roasted red peppers", "1 tbsp lemon juice", "Tahini", "3 cloves minced garlic", "1 tsp ground cumin", "0.5 tsp cayenne pepper", "1 tsp salt", "2 tbsp fresh fresh parsley", "1 cup feta cheese"]}]'::jsonb, '[{"stepIndex": 1, "text": "In an electric blender or food processor, puree the chickpeas, red peppers, feta, lemon juice, tahini, garlic, cumin, cayenne, and salt."}, {"stepIndex": 2, "text": "Process, using long pulses, until the mixture is fairly smooth, and slightly fluffy."}, {"stepIndex": 3, "text": "Make sure to scrape the mixture off the sides of the food processor or blender in between pulses."}, {"stepIndex": 4, "text": "Transfer to a serving bowl and refrigerate for at least 1 hour."}, {"stepIndex": 5, "text": "Sprinkle the hummus with the chopped parsley before serving."}]'::jsonb, 'https://db.cravecircle.cc/storage/v1/object/public/recipe-thumbnails/recipe_roasted_pepper_hummus.jpg?v=1', '@elena_bakes', 'en', '{"calories": 520, "carbsG": 58.5, "proteinG": 32.5, "fatG": 17.3, "estimated": true, "dailyCalories": 2000}'::jsonb, 'everyone')
    ON CONFLICT (id) DO UPDATE SET thumbnail_url = EXCLUDED.thumbnail_url, nutrition = EXCLUDED.nutrition;
END $$;
